CREATE TABLE course (id UUID PRIMARY KEY,slug VARCHAR(160) NOT NULL UNIQUE,category VARCHAR(120) NOT NULL,specialty VARCHAR(120),status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',academy VARCHAR(24) NOT NULL,eligible_professions TEXT,eligible_disciplines TEXT,eligible_degrees TEXT,eligible_years TEXT,instructor_id UUID,title_sq VARCHAR(255) NOT NULL,title_en VARCHAR(255) NOT NULL,description_sq TEXT,description_en TEXT,CONSTRAINT course_status_ck CHECK (status IN ('DRAFT','PUBLISHED','ARCHIVED')),CONSTRAINT course_academy_ck CHECK (academy IN ('OPEN','PROFESSIONAL')));
CREATE TABLE chapter (id UUID PRIMARY KEY,course_id UUID NOT NULL REFERENCES course(id),position INTEGER NOT NULL CHECK(position>0),title_sq VARCHAR(255) NOT NULL,title_en VARCHAR(255) NOT NULL,body_sq TEXT,body_en TEXT,UNIQUE(course_id,position));
CREATE TABLE chapter_resource (id UUID PRIMARY KEY,chapter_id UUID NOT NULL REFERENCES chapter(id),filename VARCHAR(255) NOT NULL,media_type VARCHAR(120) NOT NULL,storage_key VARCHAR(255) NOT NULL UNIQUE,byte_size BIGINT NOT NULL,download_allowed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE chapter_progress (id UUID PRIMARY KEY,user_id UUID NOT NULL,chapter_id UUID NOT NULL REFERENCES chapter(id),completed_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,chapter_id));
CREATE INDEX idx_course_status ON course(status);CREATE INDEX idx_chapter_course ON chapter(course_id);CREATE INDEX idx_progress_user ON chapter_progress(user_id);
